import java.sql.*;

public class JdbcExample {
    public static void main(String[] args) {
        String url = "jdbc:postgresql://localhost:5432/orderdb";
        String user = "dbuser";
        String password = "dbpass";

        // Connection, Statement, ResultSet auto-close with try-with-resources
        try (Connection conn = DriverManager.getConnection(url, user, password);
             PreparedStatement stmt = conn.prepareStatement(
                 "SELECT order_id, customer_name, total FROM orders WHERE total > ?")) {

            stmt.setDouble(1, 100.0); // Set parameter safely

            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    long orderId = rs.getLong("order_id");
                    String customer = rs.getString("customer_name");
                    double total = rs.getDouble("total");
                    System.out.printf("Order %d: %s - $%.2f%n", orderId, customer, total);
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

import java.sql.*;

public class CustomerQuery {
    public void findCustomersByCity(String city) {
        String url = "jdbc:postgresql://localhost:5432/shopdb";
        String sql = "SELECT customer_id, name, email FROM customers WHERE city = ?";

        // Try-with-resources ensures all components are closed automatically
        try (Connection connection = DriverManager.getConnection(url, "user", "pass");
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setString(1, city); // Bind parameter safely

            try (ResultSet resultSet = statement.executeQuery()) {
                while (resultSet.next()) { // Iterate through rows
                    long id = resultSet.getLong("customer_id");
                    String name = resultSet.getString("name");
                    String email = resultSet.getString("email");
                    System.out.printf("Customer %d: %s (%s)%n", id, name, email);
                }
            }
        } catch (SQLException e) {
            System.err.println("Database error: " + e.getMessage());
        }
    }
}

import java.sql.*;

public class ModernDriverLoading {
    public static void main(String[] args) {
        // No Class.forName() needed — driver auto-loads from classpath
        String url = "jdbc:postgresql://localhost:5432/testdb";
        String user = "postgres";
        String password = "secret";

        try (Connection conn = DriverManager.getConnection(url, user, password)) {
            System.out.println("Connected to: " + conn.getMetaData().getDatabaseProductName());
            // The PostgreSQL driver was automatically loaded because
            // postgresql-xx.x.jar is on the classpath and contains
            // META-INF/services/java.sql.Driver with org.postgresql.Driver
        } catch (SQLException e) {
            System.err.println("Connection failed: " + e.getMessage());
        }
    }
}

