import java.sql.*;
import javax.sql.DataSource;

public class OrderRepository {
    private final DataSource dataSource;

    public OrderRepository(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public void updateOrderStatus(long orderId, String newStatus) {
        String sql = "UPDATE orders SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE order_id = ?";

        // Step 1: Get Connection (auto-closed by try-with-resources)
        try (Connection conn = dataSource.getConnection();
             // Step 2: Create PreparedStatement with parameter placeholders
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            // Step 3: Set parameters (1-indexed)
            stmt.setString(1, newStatus);
            stmt.setLong(2, orderId);

            // Step 4: Execute UPDATE (returns number of affected rows)
            int rowsUpdated = stmt.executeUpdate();

            // Step 5: Process result (for UPDATE, check affected row count)
            if (rowsUpdated > 0) {
                System.out.printf("Order %d updated to status: %s%n", orderId, newStatus);
            } else {
                System.out.printf("Order %d not found%n", orderId);
            }
            // Step 6: Resources auto-closed by try-with-resources
        } catch (SQLException e) {
            throw new RuntimeException("Failed to update order", e);
        }
    }
}

import java.sql.*;

public class JdbcInterfacesDemo {
    public void demonstrateInterfaces(Connection connection) throws SQLException {
        // DatabaseMetaData: introspect database capabilities and schema
        DatabaseMetaData metaData = connection.getMetaData();
        String dbName = metaData.getDatabaseProductName();
        String dbVersion = metaData.getDatabaseProductVersion();
        System.out.printf("Connected to %s version %s%n", dbName, dbVersion);

        // PreparedStatement: execute parameterized query
        String sql = "SELECT product_id, name, price FROM products WHERE price > ?";
        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setDouble(1, 50.0);

            // ResultSet: iterate through query results
            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    long id = rs.getLong("product_id");
                    String name = rs.getString("name");
                    double price = rs.getDouble("price");
                    System.out.printf("Product %d: %s - $%.2f%n", id, name, price);
                }
            }
        }
        // All four interfaces used: Connection, DatabaseMetaData, PreparedStatement, ResultSet
    }
}

// Layer 1: JPA Entity (ORM mapping)
@Entity
@Table(name = "orders")
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long orderId;
    private String customerName;
    private Double total;
    // getters/setters omitted
}

// Layer 2: Spring Data JPA Repository (uses Hibernate → JDBC)
public interface OrderRepository extends JpaRepository<Order, Long> {
    List<Order> findByTotalGreaterThan(Double amount); // Generated SQL via JDBC
}

// Layer 3: JdbcTemplate for custom SQL (direct JDBC access)
@Repository
public class CustomOrderRepository {
    private final JdbcTemplate jdbcTemplate;

    public CustomOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public int countHighValueOrders(double threshold) {
        String sql = "SELECT COUNT(*) FROM orders WHERE total > ?";
        return jdbcTemplate.queryForObject(sql, Integer.class, threshold);
        // JdbcTemplate uses the same DataSource → JDBC Driver → Database path
    }
}
